int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int octetCount = 0;
    int len = bb.limit() - i;
    int remaining = len;
    while (remaining > 0) {
        int charCount = 0;
        int limit = remaining;
        for (int ii = i; ii < limit; ii++) {
            int c = bb.get(ii) & 0xFF;
            if (charCount == 0) {
                if (c >> 5 == 0x6 && remaining >= 2) {
                    charCount = 2;
                } else if (c >> 4 == 0xE && remaining >= 3) {
                    charCount = 3;
                } else if (c >> 3 == 0x1E && remaining >= 4) {
                    charCount = 4;
                } else {
                    throw new IllegalArgumentException("Invalid UTF-8 encoding");
                }
                sb.append((char) c);
                charCount--;
                remaining--;
            } else {
                if ((c & 0xC0) != 0x80) {
                    throw new IllegalArgumentException("Invalid UTF-8 encoding");
                }
                sb.append((char) (((c & 0x3F) << 6) | (charCount & 0x3F)));
                charCount--;
                remaining--;
            }
        }
        octetCount += charCount;
    }
    return octetCount;
}
