private List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long duration = end - start;
    int count = (int) Math.ceil(duration / FETCH_DATA_DURATION);
    long chunk = duration / count;
    for (int i = 0; i < count; i++) {
        long chunkStart = start + i * chunk;
        long chunkEnd = start + (i + 1) * chunk - 1;
        if (i == count - 1) {
            chunkEnd = end;
        }
        timeRanges.add(new TimeRange(chunkStart, chunkEnd));
    }
    return timeRanges;
}

